effect.shader:
void main(){
    vec2 px = 1.0/acScreenSize;
    float tl=dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(-px.x,-px.y)).rgb,vec3(0.333));
    float t =dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(0.0,-px.y)).rgb,vec3(0.333));
    float tr=dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(px.x,-px.y)).rgb,vec3(0.333));
    float l =dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(-px.x,0.0)).rgb,vec3(0.333));
    float r =dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(px.x,0.0)).rgb,vec3(0.333));
    float bl=dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(-px.x,px.y)).rgb,vec3(0.333));
    float bb=dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(0.0,px.y)).rgb,vec3(0.333));
    float br=dot(texture2DCv(inputImg.texture,acScreenNorm+vec2(px.x,px.y)).rgb,vec3(0.333));
    float gx = -tl - 2.0*l - bl + tr + 2.0*r + br;
    float gy = -tl - 2.0*t - tr + bl + 2.0*bb + br;
    float g = clamp(length(vec2(gx,gy))*strength, 0.0, 1.0);
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 base = (src.a>0.0? src.rgb/src.a : src.rgb)*bg;
    vec3 outc = mix(base, color.rgb, g);
    gl_FragColor = vec4(outc,1.0)*max(src.a, g);
}
